"""Self-contained scientific viewer for captured joint attention matrices."""
import json,base64,io
from pathlib import Path
import numpy as np
from PIL import Image
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
HERE=Path(__file__).resolve().parent
def main(groups,reps,records,cfg):
    (HERE/'figures').mkdir(exist_ok=True);plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#fbfaf5','axes.facecolor':'#fbfaf5'})
    summary=[];families=['orientation_single','orientation_binding','motion_direction'];fig,axes=plt.subplots(1,3,figsize=(13,4))
    for ax,f in zip(axes,families):
        phases=['instruction','moving','blank','report'] if f=='motion_direction' else ['instruction','sample','blank','query','probe']
        for head in (0,1):
            values=[]
            for phase in phases:
                rs=[r for r in records if r['family']==f and r['delay']==24 and r['phase']==phase];v=np.array([r['source_mass'][head][1] for r in rs]);values.append(float(v.mean()));summary.append(dict(family=f,phase=phase,head=head+1,n=len(v),memory_mass=float(v.mean()),memory_trial_sd=float(v.std()),visual_mass=float(1-v.mean())))
            ax.plot(phases,values,'o-',color=('#227e84','#c97649')[head],label=f'Head {head+1}')
        ax.set_ylim(0,1);ax.set_title(f.replace('orientation_','').replace('_',' ').title());ax.set_ylabel('Fraction of joint attention on memory keys');ax.tick_params(axis='x',rotation=25);ax.legend()
    fig.tight_layout();fig.savefig(HERE/'figures/source_allocation.png',dpi=160);fig.savefig(HERE/'figures/source_allocation.svg');plt.close(fig)
    # Representative final-blank maps: same key-mass color scale for all four head/source panels.
    reps_by_id={r['id']:r for r in reps};r=reps_by_id['orientation_single_blank'];w=np.frombuffer(base64.b64decode(r['weights']),dtype='<f4').reshape(2,169,2,169);maps=w[:,84,:,:];vmax=float(maps.max());fig,axes=plt.subplots(2,2,figsize=(8,7))
    for head in (0,1):
        for source in (0,1):
            ax=axes[head,source];img=Image.open(io.BytesIO(base64.b64decode(r['current' if source==0 else 'reference'].split(',')[1])));ax.imshow(img,extent=(0,100,100,0));hm=maps[head,source].reshape(13,13);im=ax.imshow(hm,extent=(0,100,100,0),interpolation='nearest',cmap='magma',vmin=0,vmax=vmax,alpha=.65);ax.set_title(f'Head {head+1} · '+('current input' if source==0 else 'memory')+f'\nsource mass {hm.sum():.1%}');ax.set_xticks([]);ax.set_yticks([])
    fig.suptitle('One receiving query at grid (6,6), last blank frame\nMemory keys shown over earlier sample only as a scene reference',fontsize=11);fig.colorbar(im,ax=axes.ravel().tolist(),shrink=.7,label='Raw joint weight per key, common scale');fig.savefig(HERE/'figures/blank_query_maps.png',dpi=160,bbox_inches='tight');fig.savefig(HERE/'figures/blank_query_maps.svg',bbox_inches='tight');plt.close(fig)
    (HERE/'summary.json').write_text(json.dumps(summary,indent=2))
    table='\n'.join(f"| {r['family']} | {r['phase']} | {r['head']} | {100*r['memory_mass']:.2f}% | {r['n']} |" for r in summary)
    report='# Attention maps: current visual input and memory\n\nFrozen attention checkpoint8400; unchanged existing tasks. This captures attention weights, not a new model experiment or an intervention.\n\n[Open the interactive scene-overlay viewer](index.html) · [Capture protocol](config.json) · [Numerical allocation summary](summary.json)\n\n## What the network contains\n\nTwo learned heads each query both sources jointly. They are **not** a dedicated visual head and a dedicated memory head. Each head produces169 receiving queries over338 keys:169 current sensory-field keys followed by169 previous-memory keys. Per query, visual mass plus memory mass is1.\n\nMaps are projected from the13×13 encoded grid to the100×100 scene for display. They index encoded receptive-field positions, not pixel attribution. A memory overlay on an earlier sample/reference provides spatial context; it is not a reconstruction of the remembered image.\n\n## Phase means at D24\n\nEach episode first contributes its mean across frames within that phase; then independent episodes are equally averaged.\n\n| Task | Phase | Head | Memory source mass | Episodes |\n|---|---|---:|---:|---:|\n'+table+'\n\n## Averaging and interpretation\n\n- Single-orientation maps split changed/unchanged trials. Motion maps split winner direction. Binding maps group the exact two native item locations; small groups display their actual n and are descriptive. We do not blur together displaced objects and call the result one spatial focus.\n- Query-averaged source-key maps show where the whole population draws content. Averages can look diffuse even when each query is sharply local. The representative viewer also exposes the full matrix for a clicked receiving query.\n- Raw joint weights use a common color scale across both heads and sources. Conditional maps explicitly normalize inside each source; their geometry must be interpreted with the displayed original source mass.\n- Receiving-site allocation maps ask which memory grid sites draw from visual versus memory keys. Source-key maps answer where their inputs originate. These are different axes of the attention matrix.\n- Current scenes are actual captured frames. Earlier sample/final-moving scenes behind memory maps are labelled remembered-scene references. Condition means overlay an example from the same location/condition group, not an average image.\n- The model, sensory traces and tasks are unchanged; one ordinary-forward equality check confirms observation. Attention weights alone do not establish causal importance or prove a preserved feature.\n\nSaved artifacts include per-trial maps and metadata, condition means, representative full matrices, static figures, numerical summaries and a standalone HTML viewer. No UMAP, tSNE, latent probes, additional training or interventions were run in this scoped visualization.\n'
    (HERE/'report.md').write_text(report,encoding='utf-8')
    svg='data:image/svg+xml;base64,'+base64.b64encode((HERE/'figures/source_allocation.svg').read_bytes()).decode()
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attention over visual input and memory</title><style>
    :root{--ink:#19373e;--teal:#267c82;--paper:#fbfaf5;--orange:#c97649}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}header{background:#19373e;color:#f6f3e9;padding:55px max(6vw,25px)}header p{max-width:850px;color:#bfd3d1}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.2em}h1{font:clamp(38px,5vw,65px)/1.12 Georgia,serif;font-weight:400;margin:17px 0}h2{font:32px Georgia,serif;font-weight:400}main{max-width:1250px;margin:auto;padding:30px 28px 65px}.card{background:white;border:1px solid #d6dfda;border-radius:12px;padding:22px;margin:22px 0}.controls{display:flex;gap:10px;flex-wrap:wrap}label{font-size:13px;font-weight:600}select{display:block;max-width:100%;padding:8px;border:1px solid #bbcfc8;border-radius:5px;background:#fff;font:14px system-ui;color:var(--ink)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:#f5f4ef;border:1px solid #e0e4dc;border-radius:9px;padding:12px}.panel h3{font-size:17px;margin:0 0 3px}.caption{font-size:12px;color:#657c7c;min-height:34px}.map{width:100%;max-height:400px;object-fit:contain;image-rendering:pixelated;cursor:crosshair}.mass{font-weight:600;font-variant-numeric:tabular-nums}.note{font-size:14px;color:#61797b}.scenes{display:flex;gap:22px;align-items:flex-start;flex-wrap:wrap}.scenes canvas{width:150px;height:150px;image-rendering:pixelated;border:1px solid #cad6d0}img{width:100%}a{color:var(--teal)}.scale{height:12px;background:linear-gradient(to right,rgba(36,98,148,.1),#ec9b45,#bc2344);border-radius:8px;max-width:450px}.scale-text{font-size:13px}math{font-size:1.1em}@media(max-width:680px){.grid{grid-template-columns:1fr}.controls{display:block}.controls label{display:block;margin:10px 0}}</style>
    <header><div class="eyebrow">Visual working memory · frozen attention8400 · captured weights</div><h1>Where does memory<br>look for its next input?</h1><p>Both learned attention heads can draw from the current sensory field and the previous memory field. Inspect each source separately, on the visual scene, through sample, movement, blanks and report.</p></header><main>
    <h2>Two heads. Two sources per head.</h2><p>The attention tensor is <strong>[B, 2, 169, 338]</strong>: two heads, 169 receiving memory queries, and 169 visual +169 memory keys. The softmax is joint across both sources. A head can change its allocation from frame to frame.</p><div class="card"><math display="block"><msub><mi>A</mi><mrow><mi>h</mi><mo>,</mo><mi>t</mi></mrow></msub><mo>=</mo><mtext>softmax</mtext><mo>(</mo><mfrac><mrow><msub><mi>Q</mi><mi>h</mi></msub><msup><mi>K</mi><mi>⊤</mi></msup></mrow><msqrt><mn>32</mn></msqrt></mfrac><mo>+</mo><mi>B</mi><mo>)</mo><mo>,</mo><mspace width="1em"/><msubsup><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mn>338</mn></msubsup><msub><mi>A</mi><mrow><mi>h</mi><mo>,</mo><mi>q</mi><mo>,</mo><mi>k</mi></mrow></msub><mo>=</mo><mn>1</mn></math></div>
    <h2>Explore scene-projected maps</h2><div class="card"><div class="controls"><label>Data<select id="mode"><option value="representative">One captured trial</option><option value="average" selected>Condition mean</option></select></label><label>Task<select id="family"><option>orientation_single</option><option>orientation_binding</option><option>motion_direction</option></select></label><label>Phase<select id="phase"></select></label><label>Trial / condition<select id="record"></select></label></div><div class="controls" style="margin-top:15px"><label>Map meaning<select id="meaning"><option value="keys">Source keys, average over receiving queries</option><option value="query">Advanced: connectivity from one receiving query</option><option value="receiver" selected>Full13×13grid: source allocation at memory sites</option></select></label><label>Normalization<select id="norm"><option value="raw">Raw joint weights</option><option value="conditional">Conditional within each source</option></select></label><label><input type="checkbox" id="overlay"> Scene overlay</label><label>Memory background<select id="background"><option value="reference">Earlier scene reference</option><option value="current">Actual current frame</option></select></label></div><p id="description" class="note"></p><div class="scenes"><div><canvas id="current" width="100" height="100"></canvas><div class="caption">Actual current scene</div></div><div><canvas id="reference" width="100" height="100"></canvas><div class="caption">Earlier sample / last moving scene<br>Spatial reference, not memory reconstruction</div></div><div><p id="querytext"></p><p class="note">Every displayed grid contains all169 receiving sites.<br>Advanced single-query connectivity is available under One captured trial.</p></div></div><div class="scale"></div><div id="scale" class="scale-text"></div></div>
    <div class="grid" id="maps"></div><div class="card"><p><strong>Read the axes carefully.</strong> Source-key maps show where inputs come from. Receiving-site maps show how each memory query divides its input between visual and memory sources. Averaging over queries can hide sharply localized individual queries.</p><p class="note">The 13×13 maps are enlarged to100×100 for display. These are encoded receptive-field positions, not pixel-level causal attribution. Conditional normalization can make a weak source look vivid; its original source mass remains displayed.</p></div>
    <h2>Average source allocation through a trial</h2><p>Each trial first contributes its phase average; trials then receive equal weight. Below, all D24 episodes are included, irrespective of label or spatial group. These plots measure total source use, not spatial localization.</p><img src="ALLOCATION"><p class="note">The visual source H already includes short opponent temporal traces. Softmax allocation is not value magnitude: initially zero memory can receive weight while contributing zero memory values.</p><h2>What was averaged?</h2><p>Single-orientation conditions split unchanged and changed trials; motion conditions split the direction that wins the duration task. Two-item binding maps keep the exact native item locations separate. Every condition displays its sample size. Scene backgrounds are representative images from that condition/location group; the heatmap is the condition average.</p><p>No new training, stimuli, interventions, clustering or latent readouts were added. We captured ordinary frozen forward passes. Attention weights reveal routing; they do not by themselves establish which stored feature caused the answer.</p><p><a href="report.md">Full report</a> · <a href="summary.json">Allocation numbers</a> · <a href="config.json">Checkpoint and capture protocol</a> · <a href="figures/blank_query_maps.png">Advanced: old single-query connectivity figure</a></p></main>
    <script>const DATA=PAYLOAD;let q=84,serial=0;const images=new Map();function img(src){if(!images.has(src)){let im=new Image();im.src=src;images.set(src,im)}return images.get(src)}function choice(id,values){let el=document.getElementById(id),old=el.value;el.innerHTML='';values.forEach(([value,label])=>{let o=document.createElement('option');o.value=value;o.textContent=label;el.append(o)});if(values.some(v=>v[0]===old))el.value=old}function items(){return document.getElementById('mode').value==='average'?DATA.groups:DATA.reps}function refresh(){let f=document.getElementById('family').value;choice('phase',[...new Set(items().filter(x=>x.family===f).map(x=>x.phase))].map(v=>[v,v]));records()}function records(){let f=document.getElementById('family').value,p=document.getElementById('phase').value;choice('record',items().filter(x=>x.family===f&&x.phase===p).map(x=>[x.id,(x.delay!==undefined?'D'+x.delay+' · ':'frame'+x.time+' · ')+x.condition+(x.n?' · n='+x.n:'')]));draw()}function array(r){if(!r.raw){let binary=atob(r.weights),bytes=new Uint8Array(binary.length);for(let i=0;i<bytes.length;i++)bytes[i]=binary.charCodeAt(i);r.raw=new Float32Array(bytes.buffer)}return r.raw}async function draw(){let version=++serial,r=items().find(x=>x.id===document.getElementById('record').value);if(!r)return;let meaning=document.getElementById('meaning').value,conditional=document.getElementById('norm').value==='conditional',average=document.getElementById('mode').value==='average';if(average&&meaning==='query'){meaning='keys';document.getElementById('meaning').value='keys'}if(meaning==='receiver'&&conditional){conditional=false;document.getElementById('norm').value='raw'}let raw=average?null:array(r),maps=[],masses=[];for(let h=0;h<2;h++){maps[h]=[];masses[h]=[];for(let s=0;s<2;s++){let a=new Array(169).fill(0);if(average){a=(meaning==='receiver'?r.receiver_map:r.key_map)[h][s].slice()}else{for(let query=0;query<169;query++)for(let k=0;k<169;k++){let value=raw[(h*169+query)*338+s*169+k];if(meaning==='receiver')a[query]+=value;else if(meaning==='query'){if(query===q)a[k]+=value}else a[k]+=value/169}}let mass=meaning==='receiver'?a.reduce((a,b)=>a+b,0)/169:a.reduce((a,b)=>a+b,0);masses[h][s]=mass;if(conditional)a=a.map(v=>mass>1e-12?v/mass:0);maps[h][s]=a}}let max=meaning==='receiver'?1:Math.max(...maps.flat(2));document.getElementById('scale').textContent='Common scale across all four maps: 0 → '+max.toPrecision(3)+(meaning==='receiver'?' source fraction':conditional?' conditional weight / key':' joint weight / key');document.getElementById('description').textContent=average?'Mean of '+r.n+' independent trials, each averaged within this phase; background is one example from this exact condition/location group.':'One actual trial; '+r.phase+' ends at frame'+r.time+'. Joint weights are captured before the E/I memory update.';document.getElementById('querytext').textContent='Selected receiving query: row '+Math.floor(q/13)+', column '+(q%13);let current=img(r.current),reference=img(r.reference);await Promise.all([current.decode(),reference.decode()]);if(version!==serial)return;document.getElementById('current').getContext('2d').drawImage(current,0,0,100,100);document.getElementById('reference').getContext('2d').drawImage(reference,0,0,100,100);let holder=document.getElementById('maps');holder.innerHTML='';for(let h=0;h<2;h++)for(let s=0;s<2;s++){let p=document.createElement('div');p.className='panel';let title=document.createElement('h3');title.textContent='Head '+(h+1)+' · '+(s?'memory source':'visual source');p.append(title);let mass=document.createElement('div');mass.className='mass';mass.textContent='Original source allocation: '+(100*masses[h][s]).toFixed(2)+'%';p.append(mass);let cap=document.createElement('div');cap.className='caption';cap.textContent=s&&document.getElementById('background').value==='reference'?'Earlier scene reference under memory-key coordinates; not reconstructed content':'Actual current frame under encoded spatial coordinates';p.append(cap);let c=document.createElement('canvas');c.width=c.height=390;c.className='map';p.append(c);holder.append(p);let ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#fff';ctx.fillRect(0,0,390,390);if(document.getElementById('overlay').checked)ctx.drawImage(s&&document.getElementById('background').value==='reference'?reference:current,0,0,390,390);for(let y=0;y<13;y++)for(let x=0;x<13;x++){let v=maps[h][s][y*13+x]/(max||1);ctx.fillStyle='rgba('+Math.round(40+190*v)+','+Math.round(125-70*v)+','+Math.round(175-100*v)+','+(document.getElementById('overlay').checked?(0.03+.74*v):.95)+')';ctx.fillRect(x*30,y*30,30,30)}ctx.strokeStyle='#ffffffaa';ctx.lineWidth=1;for(let edge=0;edge<=13;edge++){ctx.beginPath();ctx.moveTo(edge*30,0);ctx.lineTo(edge*30,390);ctx.moveTo(0,edge*30);ctx.lineTo(390,edge*30);ctx.stroke()}if(meaning==='query'){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(q%13*30,Math.floor(q/13)*30,30,30);ctx.strokeStyle='#192f35';ctx.strokeRect(q%13*30+2,Math.floor(q/13)*30+2,26,26)}c.onclick=e=>{let box=c.getBoundingClientRect(),x=Math.min(12,Math.floor((e.clientX-box.left)/box.width*13)),y=Math.min(12,Math.floor((e.clientY-box.top)/box.height*13));q=y*13+x;if(!average)document.getElementById('meaning').value='query';draw()}}}document.getElementById('mode').onchange=refresh;document.getElementById('family').onchange=refresh;document.getElementById('phase').onchange=records;for(let id of ['record','meaning','norm','background','overlay'])document.getElementById(id).onchange=draw;refresh();document.getElementById('phase').value='blank';records();</script></html>'''
    doc=doc.replace('<h2>Explore scene-projected maps</h2>','<h2>The full13×13attention grid</h2><p>Default: all169 receiving memory sites, averaged within a trial condition. Each cell shows its visual or memory source fraction, on a fixed0–1scale. Strong local connectivity is real; a map from just one query was the wrong overview.</p><p><a href="figures/phase_allocation_overview.png">Sample → blank → probe: whole-grid overview</a> · <a href="figures/phase_source_keys_overview.png">Population-averaged source keys</a> · <a href="locality_summary.json">Measured locality</a></p><img src="figures/phase_allocation_overview.png">');doc=doc.replace('ALLOCATION',svg).replace('PAYLOAD',json.dumps(dict(groups=groups,reps=reps),separators=(',',':')));(HERE/'index.html').write_text(doc,encoding='utf-8')
if __name__=='__main__':main(*[json.loads((HERE/f).read_text()) for f in ('condition_maps.json','representatives.json','pertrial_metadata.json','config.json')])
